<script setup>
import {computed, ref, onMounted, onBeforeUnmount, nextTick} from 'vue';
import {state, go, testTypeCode} from '../store';
import Icon from './Icon.vue';
import LanguageAtlas from './LanguageAtlas.vue';

const root = ref(null), selected = ref('placement'), sample = ref(''), token = ref('');
const id = computed(() => state.language === 'id');
const copy = (en, indonesian) => id.value ? indonesian : en;
const labels = computed(() => ({
    eyebrow: copy('INDONESIAN LANGUAGE. OPEN POSSIBILITIES.', 'BAHASA INDONESIA. PELUANG TANPA BATAS.'),
    title: copy('Your voice.', 'Suara Anda.'),
    titleAccent: copy('A wider world.', 'Dunia terbuka.'),
    intro: copy('Find your confidence in Indonesian. Understand your strengths, discover your next step, and turn language into possibility.', 'Temukan kepercayaan diri berbahasa Indonesia. Kenali kekuatan Anda, tentukan langkah berikutnya, dan buka peluang baru.'),
    primary: copy('Find your starting point', 'Temukan langkah pertama'),
    secondary: copy('Discover the experience', 'Kenali pengalamannya'),
    heroNote: copy('For the places you will go. And the people you will meet.', 'Untuk tempat yang akan Anda tuju. Dan orang yang akan Anda temui.'),
    aboutKicker: copy('01 / A LANGUAGE OPENS A WORLD', '01 / BAHASA MEMBUKA DUNIA'),
    aboutTitle: copy('Clarity today. Confidence tomorrow.', 'Kenali kemampuan. Buka peluang.'),
    aboutBody: copy('You have a story to tell. INBAF helps you see how you understand, express, and connect in Indonesian, so your next move feels more confident.', 'Anda memiliki cerita untuk disampaikan. INBAF membantu Anda memahami kemampuan berbahasa Indonesia, dari menangkap makna hingga menyampaikan gagasan.'),
    aboutName: copy('Indonesian Language Assessment Platform for Foreign Students', 'Platform Asesmen Bahasa Indonesia bagi Penutur Asing'),
    purpose: copy('Designed for your next chapter', 'Dirancang untuk langkah berikutnya'),
    purposes: copy(['Study with confidence', 'Connect at work', 'Feel at home in Indonesia'], ['Percaya diri dalam studi', 'Terhubung di tempat kerja', 'Lebih dekat dengan Indonesia']),
    assessmentsKicker: copy('02 / ONE PLATFORM. YOUR DIRECTION.', '02 / SATU PLATFORM. ARAH PILIHAN ANDA.'),
    assessmentsTitle: copy('Different goals. Your kind of assessment.', 'Tujuan berbeda. Pilihan yang tepat.'),
    assessmentsBody: copy('A little practice, a clearer starting point, or a milestone worth sharing. Choose what brings you here.', 'Berlatih, mengenali titik awal, atau merayakan pencapaian. Pilih asesmen yang sesuai tujuan Anda.'),
    processKicker: copy('THE EXPERIENCE / SIMPLE BY DESIGN', 'PENGALAMAN ANDA / MUDAH SEJAK AWAL'),
    processTitle: copy('Less friction. More focus.', 'Lebih mudah. Lebih fokus.'),
    processBody: copy('A clear journey from your first question to your next step.', 'Alur yang jelas, dari soal pertama hingga langkah berikutnya.'),
    sampleKicker: copy('TRY THE FEEL / AN UNSCORED SAMPLE', 'COBA PENGALAMANNYA / CONTOH TANPA NILAI'),
    sampleTitle: copy('A small word. A real connection.', 'Kata sederhana. Makna yang nyata.'),
    sampleBody: copy('Try a simple question. In an assessment, instructions, review flags, and visible save status help you stay focused on your response.', 'Coba satu soal sederhana. Dalam asesmen, petunjuk, penanda tinjauan, dan status penyimpanan membantu Anda tetap fokus pada jawaban.'),
    samplePrompt: copy('Choose the word that tells us where.', 'Pilih kata yang menunjukkan tempat.'),
    verifyKicker: copy('AN ACHIEVEMENT WITH A TRACEABLE STORY', 'PENCAPAIAN YANG DAPAT DITELUSURI'),
    verifyTitle: copy('A milestone. Made verifiable.', 'Pencapaian yang bisa diperiksa.'),
    verifyBody: copy('Eligible certification results can earn a digital certificate with a unique QR code. Check the issuer’s public record to confirm its current status.', 'Hasil sertifikasi yang memenuhi ketentuan dapat memperoleh sertifikat digital dengan QR unik. Periksa catatan penerbit untuk mengetahui status terbarunya.'),
    verifyLabel: copy('Certificate verification token', 'Token verifikasi sertifikat'),
    verifyPlaceholder: copy('Paste a token from the QR link', 'Salin token dari tautan QR'),
    verifyAction: copy('Verify certificate', 'Periksa sertifikat'),
    verifyLink: copy('Open the verification page', 'Buka halaman verifikasi'),
    faqKicker: copy('A LITTLE CLARITY, BEFORE YOU BEGIN', 'KENALI LEBIH DEKAT SEBELUM MEMULAI'),
    faqTitle: copy('Good questions. Clear answers.', 'Pertanyaan Anda. Jawaban yang jelas.'),
    finalKicker: copy('YOUR NEXT CHAPTER STARTS HERE', 'LANGKAH BERIKUTNYA DIMULAI DI SINI'),
    finalTitle: copy('The world is listening. Find your voice.', 'Dunia siap mendengar. Temukan suara Anda.'),
    finalAction: copy('Explore your possibilities', 'Jelajahi peluang Anda'),
    footerLine: copy('Language brings us closer.', 'Bahasa mendekatkan kita.'),
}));
const kinds = computed(() => [
    {code: 'practice', anchor: 'simulation', number: '01', icon: 'AudioLines', title: copy('Simulation Test', 'Tes Simulasi'), line: copy('Find your rhythm.', 'Temukan ritme Anda.'), lead: copy('A little practice. A lot more confidence.', 'Lebih siap lewat latihan.'), body: copy('Get familiar with question formats and explore your strengths before a bigger step. Build confidence, one response at a time.', 'Kenali format soal dan jelajahi kemampuan Anda sebelum mengambil langkah berikutnya. Bangun rasa percaya diri, satu jawaban demi satu jawaban.'), action: copy('Explore simulation tests', 'Jelajahi tes simulasi'), features: copy(['Get to know the question formats', 'Review permitted answers and explanations', 'Practice for your next assessment'], ['Kenali beragam format soal', 'Pelajari pembahasan yang tersedia', 'Berlatih untuk asesmen berikutnya']), word: 'Halo.', translation: copy('Every conversation starts somewhere.', 'Setiap percakapan punya awal.')},
    {code: 'placement', anchor: 'placement', number: '02', icon: 'Compass', title: copy('Placement Test', 'Tes Penempatan'), line: copy('Find your direction.', 'Temukan arah Anda.'), lead: copy('A clearer picture of where you are.', 'Kenali titik awal Anda.'), body: copy('Understand your current proficiency across the skills in your assessment. Turn a starting point into a more purposeful learning journey.', 'Pahami kemahiran Anda melalui kompetensi yang diujikan. Jadikan titik awal sebagai bekal untuk menentukan arah belajar yang lebih terarah.'), action: copy('Explore placement tests', 'Jelajahi tes penempatan'), features: copy(['See your strengths by competency', 'Explore your internal proficiency level', 'Download your placement report'], ['Kenali kekuatan per kompetensi', 'Lihat klasifikasi kemahiran internal', 'Unduh laporan penempatan']), word: 'Ke mana?', translation: copy('Where will your next step take you?', 'Ke mana langkah berikutnya membawa Anda?')},
    {code: 'certification', anchor: 'certification', number: '03', icon: 'BadgeCheck', title: copy('Certification Test', 'Tes Sertifikasi'), line: copy('Make it count.', 'Rayakan pencapaian Anda.'), lead: copy('An achievement ready for your next chapter.', 'Pencapaian untuk langkah baru.'), body: copy('Bring your skills together in a structured assessment. Eligible completed results can receive a digital certificate that others can verify.', 'Tunjukkan kemampuan Anda dalam asesmen terstruktur. Hasil akhir yang memenuhi ketentuan dapat memperoleh sertifikat digital yang bisa diverifikasi.'), action: copy('Explore certification tests', 'Jelajahi tes sertifikasi'), features: copy(['Structured assessment and scoring', 'Writing and speaking reviewed when included', 'QR verification for eligible certificates'], ['Asesmen dan penilaian terstruktur', 'Tinjauan writing dan speaking jika diujikan', 'Verifikasi QR untuk sertifikat yang memenuhi syarat']), word: 'Bisa.', translation: copy('A small word for a world of possibility.', 'Kata sederhana untuk segala kemungkinan.')},
]);
const active = computed(() => kinds.value.find(kind => kind.code === selected.value) || kinds.value[1]);
const activeType = computed(() => state.test_types.find(type => type.code === selected.value));
const activePackages = computed(() => state.packages.filter(item => testTypeCode(item) === selected.value));
const unavailable = computed(() => !activeType.value || activeType.value.active === false);
const configuredName = computed(() => id.value ? activeType.value?.name : activeType.value?.name_en || activeType.value?.name);
const steps = computed(() => [
    {icon: 'Compass', title: copy('Choose your direction', 'Pilih arah Anda'), body: copy('Pick an assessment for your goal. Review its skills, timing, and requirements before you begin.', 'Pilih asesmen sesuai tujuan. Periksa kompetensi, waktu, dan ketentuannya sebelum memulai.')},
    {icon: 'PenLine', title: copy('Make room for your voice', 'Sampaikan kemampuan Anda'), body: copy('Follow clear instructions and answer at your best. Saved responses stay with your assessment.', 'Ikuti petunjuk yang jelas dan berikan jawaban terbaik. Jawaban tersimpan tetap tercatat pada asesmen Anda.')},
    {icon: 'ChartNoAxesCombined', title: copy('See your next step', 'Lihat langkah berikutnya'), body: copy('Explore your results by competency. Final results become available after any required manual review.', 'Jelajahi hasil per kompetensi. Hasil akhir tersedia setelah penilaian manual yang diperlukan selesai.')},
]);
const faqs = computed(() => [
    [copy('Who is INBAF for?', 'Untuk siapa INBAF?'), copy('International students, professionals, researchers, and anyone learning Indonesian as a foreign language. Choose an assessment that fits your goal and the skills you want to understand.', 'Mahasiswa internasional, profesional, peneliti, dan siapa pun yang mempelajari Bahasa Indonesia sebagai bahasa asing. Pilih asesmen yang sesuai tujuan serta kompetensi yang ingin Anda pahami.')],
    [copy('How do simulation, placement, and certification differ?', 'Apa perbedaan simulasi, penempatan, dan sertifikasi?'), copy('Simulation helps you practice. Placement helps you understand your starting point and download a placement report. Certification is a structured assessment with digital certificates issued only when the result meets the institution’s conditions.', 'Simulasi membantu Anda berlatih. Penempatan membantu mengenali titik awal dan menyediakan laporan penempatan. Sertifikasi adalah asesmen terstruktur dengan sertifikat digital yang diterbitkan hanya jika hasil memenuhi ketentuan lembaga.')],
    [copy('When will my results be ready?', 'Kapan hasil saya tersedia?'), copy('Objective responses are scored automatically. If your assessment includes writing or speaking, the final result waits for an assessor’s review using the assessment rubric.', 'Jawaban objektif dinilai otomatis. Jika asesmen mencakup writing atau speaking, hasil akhir menunggu tinjauan penilai menggunakan rubrik asesmen.')],
    [copy('What happens if my connection drops?', 'Bagaimana jika koneksi terputus?'), copy('Responses awaiting upload are buffered on your device and retried when the connection returns. The server timer continues for timed assessments. Use a stable connection and check the visible save status.', 'Jawaban yang belum terkirim disimpan sementara di perangkat dan dicoba kembali saat koneksi pulih. Timer server terus berjalan pada asesmen berbatas waktu. Gunakan koneksi stabil dan periksa status penyimpanan.')],
    [copy('What does an INBAF proficiency level mean?', 'Apa arti level kemahiran INBAF?'), copy('A1–C2 are internal INBAF classifications configured by the assessment institution. They do not establish official equivalence to CEFR, TOEFL, UKBI, or other certifications without empirical validation.', 'A1–C2 merupakan klasifikasi internal INBAF yang dikonfigurasi lembaga penyelenggara. Level ini tidak menyatakan kesetaraan resmi dengan CEFR, TOEFL, UKBI, atau sertifikasi lain tanpa validasi empiris.')],
]);
const ribbonLines = Array.from({length: 23}, (_, index) => ({
    d: 'M ' + (180 + index * 8) + ' 535 C ' + (180 - index * 6) + ' ' + (160 - index * 3) + ', ' + (850 - index * 8) + ' ' + (-80 + index * 8) + ', ' + (830 - index * 6) + ' ' + (230 + index * 4) + ' S ' + (430 + index * 5) + ' ' + (460 - index * 4) + ', ' + (610 + index * 4) + ' ' + (70 + index * 7),
    opacity: .24 + index * .025,
}));
let observer, mediaQuery;
function choose(code) { if (kinds.value.some(kind => kind.code === code)) selected.value = code; }
function startAssessment(code = selected.value) {
    const type = state.test_types.find(item => item.code === code);
    if (!type || type.active === false) return;
    go((state.user ? '/tests' : state.settings.registration_enabled === false ? '/login' : '/register') + '?test_type=' + code);
}
function syncHash() {
    const anchor = location.hash.slice(1);
    const kind = kinds.value.find(item => item.anchor === anchor);
    if (kind) choose(kind.code);
}
function navigateAnchor(event) {
    const kind = kinds.value.find(item => item.anchor === event.detail?.id);
    if (kind) choose(kind.code);
}
async function jump(event, anchor) {
    event.preventDefault();
    if (location.hash !== '#' + anchor) history.pushState({}, '', '#' + anchor);
    syncHash();
    await nextTick();
    document.getElementById(anchor)?.scrollIntoView({behavior: mediaQuery?.matches ? 'instant' : 'smooth', block: 'start'});
}
function verifyCertificate() { if (token.value.trim()) go('/verify/' + encodeURIComponent(token.value.trim())); }
onMounted(async () => {
    mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    window.addEventListener('hashchange', syncHash);
    window.addEventListener('popstate', syncHash);
    window.addEventListener('inbaf:landing-anchor', navigateAnchor);
    syncHash();
    if ('IntersectionObserver' in window && !mediaQuery.matches) {
        observer = new IntersectionObserver(entries => entries.forEach(entry => {
            if (entry.isIntersecting) {entry.target.classList.add('lp-in-view'); observer.unobserve(entry.target);}
        }), {threshold: .08, rootMargin: '0px 0px 20px 0px'});
        root.value?.querySelectorAll('[data-reveal]').forEach(element => {element.classList.add('lp-will-reveal'); observer.observe(element);});
    }
    await nextTick();
    if (location.hash) requestAnimationFrame(() => document.getElementById(location.hash.slice(1))?.scrollIntoView({block: 'start', behavior: 'instant'}));
});
onBeforeUnmount(() => {observer?.disconnect(); window.removeEventListener('hashchange', syncHash); window.removeEventListener('popstate', syncHash); window.removeEventListener('inbaf:landing-anchor', navigateAnchor);});
</script>

<template>
<main id="landing-content" ref="root" class="landing-redesign" :class="{'lp-dark':state.dark}" tabindex="-1">
    <section id="home" class="lp-hero" aria-labelledby="lp-hero-title">
        <div class="lp-hero-stage">
            <div class="lp-hero-eyebrow"><span class="lp-signal"></span>{{ labels.eyebrow }}<span class="lp-edition">INBAF / {{new Date().getFullYear()}}</span></div>
            <div class="lp-ribbon" aria-hidden="true">
                <svg viewBox="0 0 1000 650" fill="none" focusable="false"><defs><linearGradient id="lp-ribbon-gradient" x1="140" y1="480" x2="870" y2="80" gradientUnits="userSpaceOnUse"><stop stop-color="#6ce5bb" stop-opacity=".12"/><stop offset=".4" stop-color="#a9fbd2"/><stop offset=".7" stop-color="#66d0c0"/><stop offset="1" stop-color="#bdabef"/></linearGradient></defs><path v-for="(line,index) in ribbonLines" :key="index" :d="line.d" stroke="url(#lp-ribbon-gradient)" :opacity="line.opacity" :stroke-width="index % 5 === 0 ? 2 : 1.15"/><path d="M 80 550 H 920 M 920 550 V 120" stroke="#8ee6c2" stroke-opacity=".14" stroke-dasharray="2 8"/><circle cx="920" cy="550" r="4" fill="#b7f8d2"/></svg>
                <span class="lp-language-label">Halo<span>{{copy('hello / a new beginning','sapaan / sebuah awal baru')}}</span></span>
            </div>
            <h1 id="lp-hero-title" class="lp-hero-title">{{ labels.title }}<span>{{ labels.titleAccent }}<svg viewBox="0 0 66 66" aria-hidden="true"><path d="M33 1V65M1 33H65M10 10L56 56M10 56L56 10" fill="none" stroke="currentColor" stroke-width="5"/></svg></span></h1>
            <div class="lp-hero-bottom"><div><p class="lp-hero-intro">{{ labels.intro }}</p><div class="lp-hero-cta"><a class="lp-button lp-button-mint" href="#assessments" @click="jump($event,'assessments')">{{labels.primary}}<Icon name="ArrowUpRight" :size="22"/></a><a class="lp-text-link lp-hero-discover" href="#how-it-works" @click="jump($event,'how-it-works')">{{labels.secondary}}<Icon name="ArrowDown" :size="19"/></a></div></div><p class="lp-hero-aside"><Icon name="Globe2" :size="30"/>{{ labels.heroNote }}<span>BAHASA INDONESIA / {{copy('YOUR CONNECTION TO WHAT’S NEXT','TERHUBUNG DENGAN LANGKAH BARU')}}</span></p></div>
        </div>
        <div class="lp-directions"><a v-for="kind in kinds" :key="kind.code" :href="'#'+kind.anchor" @click="jump($event,kind.anchor)"><span class="lp-direction-number">{{kind.number}}</span><span><small>{{kind.title}}</small><strong>{{kind.line}}</strong></span><Icon name="ArrowUpRight" :size="24"/></a></div>
    </section>

    <section id="about" class="lp-about lp-container" aria-labelledby="lp-about-title" data-reveal>
        <div class="lp-kicker">{{ labels.aboutKicker }}</div>
        <div class="lp-about-grid"><div><h2 id="lp-about-title">{{labels.aboutTitle}}</h2><p class="lp-about-name">{{labels.aboutName}}</p></div><div><p class="lp-body-large">{{labels.aboutBody}}</p><div class="lp-purpose-list"><span>{{labels.purpose}}</span><p v-for="(purpose,index) in labels.purposes" :key="purpose"><Icon :name="['GraduationCap','BriefcaseBusiness','MessagesSquare'][index]" :size="22"/>{{purpose}}<Icon name="ArrowUpRight" :size="18"/></p></div></div></div>
        <div class="lp-about-foot"><span><Icon name="ShieldCheck" :size="20"/>{{copy('A secure space for your next step','Ruang aman untuk langkah Anda')}}</span><span>{{copy('Built around real language. And real life.','Tentang bahasa yang hidup. Dan kehidupan nyata.')}}</span></div>
    </section>

    <section id="assessments" class="lp-assessments" aria-labelledby="lp-assessments-title">
        <div class="lp-container">
            <div class="lp-section-heading" data-reveal><div><div class="lp-kicker">{{labels.assessmentsKicker}}</div><h2 id="lp-assessments-title">{{labels.assessmentsTitle}}</h2></div><p>{{labels.assessmentsBody}}</p></div>
            <div class="lp-assessment-selector" :aria-label="copy('Choose an assessment type','Pilih jenis asesmen')"><div v-for="kind in kinds" :id="kind.anchor" :key="kind.code" class="lp-assessment-choice"><button class="lp-assessment-tab" :class="{selected:selected===kind.code}" :aria-pressed="selected===kind.code" aria-controls="lp-assessment-detail" @click="choose(kind.code)"><span>{{kind.number}}</span><Icon :name="kind.icon" :size="27"/><strong>{{kind.title}}</strong><Icon name="ArrowDown" :size="20"/></button></div></div>
            <div id="lp-assessment-detail" class="lp-assessment-panel" :class="selected" aria-live="polite" aria-atomic="true">
                <div class="lp-assessment-story"><span class="lp-kicker">{{active.number}} / {{active.title}}</span><h3>{{active.lead}}</h3><p>{{active.body}}</p><ul><li v-for="feature in active.features" :key="feature"><Icon name="Check" :size="20"/>{{feature}}</li></ul><button class="lp-button lp-button-deep lp-assessment-start" :disabled="unavailable" @click="startAssessment()">{{unavailable?copy('Currently unavailable','Belum tersedia'):active.action}}<Icon name="ArrowUpRight" :size="21"/></button><span class="lp-package-availability">{{activePackages.length?activePackages.length+' '+copy('published assessments','paket tersedia'):copy('Browse this category for current availability','Lihat ketersediaan terbaru pada kategori ini')}}<span v-if="configuredName"> · {{configuredName}}</span></span></div>
                <div class="lp-assessment-art" aria-hidden="true">
                    <div class="lp-type-coordinate"><span>INBAF / {{active.number}}</span><Icon :name="active.icon" :size="28"/></div>
                    <svg class="lp-type-drawing" viewBox="0 0 480 270" fill="none" focusable="false">
                        <g v-if="selected==='practice'" stroke="currentColor" stroke-linecap="round"><path v-for="(height,index) in [32,70,116,170,208,152,96,52,110,180,216,162,92,44,82,140,188,136,72,30]" :key="index" :d="'M'+(42+index*21)+' '+(135-height/2)+'V'+(135+height/2)" :stroke-width="index===10?11:7" :opacity=".28+index%4*.18"/></g>
                        <g v-else-if="selected==='placement'" stroke="currentColor"><path d="M48 223H112V183H180V142H250V100H320V58H430" stroke-width="2"/><path d="M48 238H448M48 238V32" stroke-dasharray="2 7" opacity=".35"/><path d="M85 211C151 128 216 195 281 104S365 67 414 37" stroke-width="3" stroke-dasharray="5 5" opacity=".5"/><g v-for="(point,index) in [[112,183],[180,142],[250,100],[320,58]]" :key="index"><circle :cx="point[0]" :cy="point[1]" r="9" fill="currentColor"/><circle :cx="point[0]" :cy="point[1]" r="17" opacity=".2"/></g><path d="M402 38L417 33L414 49" stroke-width="3" stroke-linejoin="round"/></g>
                        <g v-else stroke="currentColor"><path d="M140 35H335V199H140Z" stroke-width="1.5" transform="rotate(-9 237 117)" opacity=".4"/><path d="M117 58H312V222H117Z" stroke-width="1.5" transform="rotate(8 214 140)" opacity=".35"/><rect x="139" y="35" width="201" height="193" rx="4" fill="var(--lp-art-bg)" stroke-width="1.5"/><path d="M164 65H316M164 81H253M164 174H248M164 187H225" opacity=".4"/><path d="M190 110L215 135L270 84" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="M278 164H290V176H278ZM299 164H311V176H299ZM278 185H290V197H278ZM300 186H305V191H300Z" stroke-width="2"/><circle cx="240" cy="140" r="49" opacity=".25"/></g>
                    </svg><strong class="lp-language-word">{{active.word}}</strong><span class="lp-language-translation">{{active.translation}}</span><span class="lp-art-footer">{{copy('YOUR NEXT STEP, IN INDONESIAN','LANGKAH BERIKUTNYA, DALAM BAHASA INDONESIA')}}<Icon name="ArrowUpRight" :size="20"/></span>
                </div>
            </div>
        </div>
    </section>

    <LanguageAtlas/>

    <section id="how-it-works" class="lp-process lp-container" aria-labelledby="lp-process-title">
        <div class="lp-section-heading" data-reveal><div><div class="lp-kicker">{{labels.processKicker}}</div><h2 id="lp-process-title">{{labels.processTitle}}</h2></div><p>{{labels.processBody}}</p></div>
        <ol class="lp-process-steps"><li v-for="(step,index) in steps" :key="index" data-reveal><span class="lp-step-top"><span>0{{index+1}}</span><Icon :name="step.icon" :size="30"/></span><h3>{{step.title}}</h3><p>{{step.body}}</p></li></ol>
        <div class="lp-sample" data-reveal><div class="lp-sample-intro"><div class="lp-kicker">{{labels.sampleKicker}}</div><h3>{{labels.sampleTitle}}</h3><p>{{labels.sampleBody}}</p><span><Icon name="CloudCheck" :size="21"/>{{copy('Clear instructions. Visible save status. Your own pace of navigation.','Petunjuk jelas. Status tersimpan. Navigasi yang mudah.')}}</span></div><div class="lp-sample-question"><span>{{labels.samplePrompt}}</span><p lang="id">Saya tinggal <span class="lp-sample-blank">{{sample||'___'}}</span> Jakarta.</p><div class="lp-sample-options" :aria-label="copy('Sample answer choices','Pilihan jawaban contoh')"><button v-for="(answer,index) in ['di','ke','dari']" :key="answer" :aria-pressed="sample===answer" :class="{selected:sample===answer}" @click="sample=answer"><small>{{String.fromCharCode(65+index)}}</small>{{answer}}<Icon v-if="sample===answer" :name="answer==='di'?'Check':'RefreshCw'" :size="18"/></button></div><p class="lp-sample-feedback" aria-live="polite">{{!sample?copy('A quick introduction to the experience. No score. No sign-up.','Kenalan singkat dengan pengalaman ujian. Tanpa nilai. Tanpa mendaftar.'):sample==='di'?copy('Exactly. “Di” tells us where someone lives.','Tepat. Kata “di” menunjukkan tempat tinggal.'):copy('Give it another try. Which word describes a location?','Coba lagi. Kata mana yang menunjukkan tempat?')}}</p></div></div>
